<?php
declare(strict_types=1);
/**
 * Rebuild unclaimed goods gifts, consignment and presale rights from JSJ.
 * Source kind and source ID keep each entitlement distinct; target store is
 * always the resolved member's store, even when the JSJ business store differs.
 */
$args=array_fill_keys(array_slice($argv,1),true);if(!isset($args['--execute'],$args['--allow-ruihao'],$args['--after-cleanup'],$args['--direct-jsj'])){fwrite(STDERR,"Refusing to write without --execute --allow-ruihao --after-cleanup --direct-jsj\n");exit(2);}
$env=parse_ini_file(getenv('RH_ENV_FILE')?:'/www/wwwroot/rh.cc3798.com/.env',true,INI_SCANNER_RAW);$db=$env['DATABASE']??[];$target=getenv('RH_TARGET_DATABASE')?:($db['DATABASE']??'');if($target!=='ruihao')throw new RuntimeException("target guard failed: $target");
$pdo=new PDO('mysql:host='.$db['HOSTNAME'].';port='.$db['HOSTPORT'].';dbname=ruihao;charset=utf8mb4',$db['USERNAME'],$db['PASSWORD'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$pdo->exec('SET NAMES utf8mb4 COLLATE utf8mb4_general_ci');
$pdo->beginTransaction();try{
 $pdo->exec('DROP TEMPORARY TABLE IF EXISTS tmp_rh_goods');
 $pdo->exec("CREATE TEMPORARY TABLE tmp_rh_goods AS SELECT g.*,m.target_uid,m.target_store_id,c.id product_id,av.id sku_id,av.`unique` sku_unique,COALESCE(g.occurred_at,0) occurred_ts
  FROM (
    SELECT 'GIFT' source_kind,CONVERT(g.id USING utf8mb4) source_id,CONVERT(g.CustomerId USING utf8mb4) source_customer_id,CONVERT(COALESCE(g.Shop,'') USING utf8mb4) source_shop_id,CONVERT(g.GoodsId USING utf8mb4) source_goods_id,LEFT(COALESCE(bg.GoodsName,''),255) goods_name,ROUND(g.Quantity-COALESCE(g.ConsumeQuantity,0),0) remain_qty_target,COALESCE(UNIX_TIMESTAMP(g.IssueDate),UNIX_TIMESTAMP(g.SendDate),UNIX_TIMESTAMP('2026-09-17 00:00:00')) occurred_at FROM jsj.SS_SendGoods g JOIN jsj.bd_goods bg ON bg.Id=g.GoodsId WHERE g.EffectiveDate>='2026-09-17' AND g.Fstate='0' AND g.Quantity-COALESCE(g.ConsumeQuantity,0)>0
    UNION ALL SELECT 'STORED',CONVERT(g.id USING utf8mb4),CONVERT(g.CustomerId USING utf8mb4),CONVERT(COALESCE(g.Shop,'') USING utf8mb4),CONVERT(g.GoodsId USING utf8mb4),LEFT(COALESCE(bg.GoodsName,''),255),ROUND(g.Quantity-COALESCE(g.ConsumeQuantity,0),0),COALESCE(UNIX_TIMESTAMP(g.IssueDate),UNIX_TIMESTAMP(g.SendDate),UNIX_TIMESTAMP('2026-09-17 00:00:00')) FROM jsj.SS_StoreGoods g JOIN jsj.bd_goods bg ON bg.Id=g.GoodsId WHERE g.EffectiveDate>='2026-09-17' AND g.Quantity-COALESCE(g.ConsumeQuantity,0)>0 AND g.Fstate<>'-1' AND COALESCE(g.Salefstate,'')<>'作废'
    UNION ALL SELECT 'PRESALE',CONVERT(g.id USING utf8mb4),CONVERT(g.CustomerId USING utf8mb4),CONVERT(COALESCE(g.ShopId,'') USING utf8mb4),CONVERT(g.GoodsId USING utf8mb4),LEFT(COALESCE(bg.GoodsName,''),255),ROUND(g.quantity-COALESCE(g.consumequantity,0),0),COALESCE(UNIX_TIMESTAMP(g.IssueDate),UNIX_TIMESTAMP(g.PreSaleDate),UNIX_TIMESTAMP('2026-09-17 00:00:00')) FROM jsj.SS_PreSaleGoods g JOIN jsj.bd_goods bg ON bg.Id=g.GoodsId WHERE g.quantity-COALESCE(g.consumequantity,0)>0 AND g.Fstate<>'-1'
  ) g JOIN mig_jsj_20260917_member_resolution m ON m.source_customer_id=g.source_customer_id COLLATE utf8mb4_general_ci
  JOIN eb_store_product c ON c.keyword=CONCAT('RH_GOODS:',g.source_goods_id,':STORE:',m.target_store_id) AND c.type=1 AND c.product_type=0 AND c.is_del=0
  JOIN eb_store_product_attr_value av ON av.product_id=c.id AND av.product_type=0");
 $pdo->exec('ALTER TABLE tmp_rh_goods ADD PRIMARY KEY(source_kind,source_id)');
 $source=(int)$pdo->query("SELECT COUNT(*) FROM (SELECT g.id FROM jsj.SS_SendGoods g JOIN jsj.bd_goods bg ON bg.Id=g.GoodsId WHERE g.EffectiveDate>='2026-09-17' AND g.Fstate='0' AND g.Quantity-COALESCE(g.ConsumeQuantity,0)>0 UNION ALL SELECT g.id FROM jsj.SS_StoreGoods g JOIN jsj.bd_goods bg ON bg.Id=g.GoodsId WHERE g.EffectiveDate>='2026-09-17' AND g.Quantity-COALESCE(g.ConsumeQuantity,0)>0 AND g.Fstate<>'-1' AND COALESCE(g.Salefstate,'')<>'作废' UNION ALL SELECT g.id FROM jsj.SS_PreSaleGoods g JOIN jsj.bd_goods bg ON bg.Id=g.GoodsId WHERE g.quantity-COALESCE(g.consumequantity,0)>0 AND g.Fstate<>'-1') x")->fetchColumn();$resolved=(int)$pdo->query('SELECT COUNT(*) FROM tmp_rh_goods')->fetchColumn();if($source!==$resolved)throw new RuntimeException("goods preflight failed: $resolved/$source resolved");
 // 会员是商品权益的唯一业务匹配键；跨店来源统一落到会员所属门店，
 // 来源门店只作为追溯字段，不能用门店内连接过滤会员资产。
 $pdo->exec("INSERT INTO eb_cashier_v3_presale_claimable_line(claimable_line_id,source_kind,gift_id,gift_item_id,tenant_id,organization_id,organization_path_snapshot,organization_name_snapshot,store_id,store_name_snapshot,source_order_id,source_order_no_snapshot,source_order_line_id,source_checkout_request_id,member_id,member_name_snapshot,member_phone_snapshot,product_id,sku_id,sku_unique_snapshot,product_name_snapshot,quantity,claimed_quantity,claim_status,close_operation_id,closed_at,version,business_date,occurred_at,settled_at,recorded_at,created_at,updated_at)
  SELECT CONCAT('RH102-',LOWER(g.source_kind),'-',g.source_id),CASE WHEN g.source_kind='GIFT' THEN 'GIFT' ELSE 'PRESALE' END,CONCAT('JSJ-',g.source_kind,'-',g.source_id),CONCAT('JSJ-',g.source_kind,'-',g.source_id),'0',COALESCE(os.org_id,0),'','',g.target_store_id,LEFT(COALESCE(s.name,''),128),CONCAT('RH-RELOAD-102-GOODS-',g.source_kind,'-',g.source_id),CONCAT('JSJ-',g.source_kind,'-',g.source_id),CONCAT('JSJ-',g.source_kind,'-',g.source_id),'JSJ-20260917-R1',g.target_uid,LEFT(COALESCE(u.real_name,''),128),LEFT(COALESCE(u.phone,''),32),g.product_id,g.sku_id,g.sku_unique,LEFT(g.goods_name,255),g.remain_qty_target,0,'OPEN','',0,1,DATE(FROM_UNIXTIME(g.occurred_ts)),g.occurred_ts,g.occurred_ts,g.occurred_ts,UNIX_TIMESTAMP(),UNIX_TIMESTAMP()
  FROM tmp_rh_goods g JOIN eb_user u ON u.uid=g.target_uid LEFT JOIN eb_system_store s ON s.id=g.target_store_id LEFT JOIN eb_organization_store os ON os.store_id=g.target_store_id LEFT JOIN eb_cashier_v3_presale_claimable_line existing ON existing.tenant_id='0' AND existing.claimable_line_id=CONCAT('RH102-',LOWER(g.source_kind),'-',g.source_id) WHERE existing.id IS NULL");
 $pdo->commit();
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
echo json_encode($pdo->query("SELECT source_kind,COUNT(*) rows,SUM(quantity) quantity FROM eb_cashier_v3_presale_claimable_line WHERE source_checkout_request_id='JSJ-20260917-R1' GROUP BY source_kind")->fetchAll(PDO::FETCH_ASSOC),JSON_UNESCAPED_UNICODE).PHP_EOL;
